                    and grid[r][c-1] == grid[r][c+1] == 3):
                crosses.append((r, c, grid[r][c]))

    arms = set()
    for r, c, _ in crosses:
        arms.update(((r-1,c), (r+1,c), (r,c-1), (r,c+1)))

    def ray_cells(r, c, dr, dc):
        cells = []
        i, j = r + dr, c + dc
        own_arm = (i, j) in {(r-1,c), (r+1,c), (r,c-1), (r,c+1)}
