            if grid[i][j] == 3 and (i, j) in arms and not own_arm:
                break
            cells.append((i, j))
            i += dr
            j += dc
            own_arm = False
        return cells

    # Horizontal rays are drawn first, then vertical rays. Empty-center
    # crosses (color 0) erase earlier rays on their tracks; vertical tracks
    # take precedence where horizontal and vertical tracks intersect.
    for r, c, color in crosses:
        for dc in (-1, 1):
            for i, j in ray_cells(r, c, 0, dc):
                if grid[i][j] == 0:
