    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    crosses = []
    for r in range(h):
        for c in range(w):
            if (0 < r < h - 1 and 0 < c < w - 1
                    and grid[r-1][c] == grid[r+1][c] == 3
                    and grid[r][c-1] == grid[r][c+1] == 3):
                crosses.append((r, c, grid[r][c]))

    all_arms = set()
    for r, c, _ in crosses:
        all_arms.update(((r-1, c), (r+1, c), (r, c-1), (r, c+1)))

    def ray(r, c, dr, dc):
        own_arms = {(r-1, c), (r+1, c), (r, c-1), (r, c+1)}
        cells = []
        i, j = r + dr, c + dc
        while 0 <= i < h and 0 <= j < w:
            # A marker arm belonging to another plus is a barrier; source arms
            # themselves are traversed and left unchanged in the input.
            if grid[i][j] == 3 and (i, j) in all_arms and (i, j) not in own_arms:
                break
            cells.append((i, j))
            i += dr
            j += dc
        return cells

    # Each plus projects its center color in four cardinal directions. Rays
    # pass through their own arms but stop before a different plus's arm.
    # Empty-center pluses project 0 and can therefore erase generated color
    # along their row/column; original nonzero input cells are retained.
    for r, c, color in crosses:
        for dc in (-1, 1):
            for i, j in ray(r, c, 0, dc):
                if grid[i][j] == 0:
                    out[i][j] = color
    for r, c, color in crosses:
        for dr in (-1, 1):
            for i, j in ray(r, c, dr, 0):
                if grid[i][j] == 0:
                    out[i][j] = color
    return out
